with months as (select date_trunc('month', date_day) as month_start, max(date_day) as m_last from {{ ref('time_spine') }} group by 1), eligible as (select m.member_id, ms.month_start from (select distinct member_id from {{ ref('members') }}) m cross join months ms where exists (select 1 from {{ ref('cards') }} c where c.member_id = m.member_id and c.card_type in ('悦享年卡','家庭季卡') and c.valid_from <= ms.m_last and (c.valid_until is null or ms.m_last < c.valid_until) and (c.ended_at is null or ms.m_last < c.ended_at))), valid_orders as (select member_id, date_trunc('month', ordered_at) as month_start, order_id, paid_cents - refund_cents as net_cents from {{ ref('orders') }} where status = 'paid' and paid_cents - refund_cents > 0), agg as (select member_id, month_start, count(distinct order_id) as valid_order_cnt, sum(net_cents) as net_cents_sum from valid_orders group by 1, 2) select e.member_id, e.month_start, a.valid_order_cnt, a.net_cents_sum from eligible e inner join agg a on e.member_id = a.member_id and e.month_start = a.month_start